CREATE TABLE IF NOT EXISTS `cmy_ems_tpl` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(128) DEFAULT 'smsbao' COMMENT '模板名称',
  `event` varchar(128) DEFAULT '' COMMENT '事件名',
  `subject` varchar(500) COMMENT '邮件标题',
  `body` text COMMENT '邮件内容',
  `remark` varchar(400) COMMENT '备注', 
  `status` tinyint(2) NOT NULL DEFAULT '1' COMMENT '启用状态 1启用0禁用',
  `createtime` int(10) unsigned DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  INDEX `event` (`event`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='系统邮件模板';

INSERT INTO `cmy_ems_tpl` (`id`, `name`, `event`, `subject`, `body`, `remark`, `status`, `createtime`) VALUES
(1, '验证码', 'send_code', '您有新的验证码 - {site_sitename}', '<meta charset="UTF-8">  <meta http-equiv="X-UA-Compatible" content="IE=edge">  <meta name="viewport" content="width=device-width, initial-scale=1.0">  <title>Document</title>  <style>    li{list-style: none;}    a{text-decoration: none;}    body{margin: 0;}    .box{      background-color: #EBEBEB;      height: 100%;    }    .logo_top {padding: 20px 0; width: 175px;  margin: auto;}    .logo_top img{      display: block;  width: 100%;      margin: 0 auto;    }    .card{      width: 650px;      margin: 0 auto;      background-color: white;      font-size: 0.8rem;      line-height: 22px;      padding: 40px 50px;      box-sizing: border-box;    }    .contimg{      text-align: center;    }    button{      background-color: #F75697;      padding: 8px 16px;      border-radius: 6px;      outline: none;      color: white;      border: 0;    }    .lvst{      color: #57AC80;    }    .banquan{      display: flex;      justify-content: center;      flex-wrap: nowrap;      color: #B7B8B9;      font-size: 0.4rem;      padding: 20px 0;      margin: 0;      padding-left: 0;    }    .banquan li span{      display: inline-block;      padding: 0 8px;    }    @media (max-width: 650px){      .card{        padding: 5% 5%;      }      .logo_top img,.contimg img{width: 280px;}      .box{height: auto;}      .card{width: auto;}    }    @media (max-width: 280px){.logo_top img,.contimg img{width: 100%;}}  </style><div class="box"><div class="logo_top"><img src="{site_logo}" alt=""/></div><div class="card"><h1 style="text-align: center;">你有新的验证码<br/></h1><br/><strong>尊敬的用户</strong><span style="background-color: rgb(235, 235, 235); font-size: 14px;">{user_username}</span></div><div class="card"><span style="font-size: 1.35rem;">您的验证码是</span><font size="10">{code}</font><span style="font-size: 1.65rem;">, 5 分钟内有效。如非本人操作请忽略</span></div><div class="card"><span style="font-size: 0.8rem;"> </span><span style="font-size: 0.8rem; display: inline-block; width: 100%; text-align: right;"><span style="font-size: 16px;">{site_sitename}</span><br/></span></div><div class="card"><span style="margin: 0; padding: 0; margin-top: 20px; display: inline-block; width: 100%; text-align: right;">{time}</span></div><ul class="banquan"><li>{site_company}<br/></li></ul></div>', '', 1, 1688565175),
(2, '找回密码', 'findpwd', '您正在找回密码 - {site_sitename}', '<meta charset="UTF-8">\n<meta http-equiv="X-UA-Compatible" content="IE=edge">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Document</title>\n<style>\n    li {\n        list-style: none;\n    }\n\n    a {\n        text-decoration: none;\n    }\n\n    html,\n    body {\n        margin: 0 !important;\n        font-size: 16px !important;\n    }\n\n    .box {\n        background-color: #f1f1f1;\n        height: 100%;\n        padding-bottom: 135px;\n    }\n\n    .logo_top {\n        padding: 20px 0;\n    width: 175px;  margin: auto;}\n\n    .logo_top img {\n        display: block;\n    width: 100%;\n        margin: 0 auto;\n}\n\n    .card {\n        width: 650px;\n        margin: 0 auto;\n        background-color: white;\n        font-size: 0.8rem;\n        line-height: 22px;\n        padding: 40px 50px;\n        box-sizing: border-box;\n    }\n\n    .card-footer {\n        display: flex;\n        justify-content: space-between;\n    }\n\n    .card-footer span.left {\n        font-size: 1.05rem;\n        display: inline-block;\n        width: 100%;\n        text-align: left;\n    }\n\n    .card-footer span.right {\n        font-size: 1.05rem;\n        display: inline-block;\n        width: 100%;\n        text-align: right;\n    }\n\n    .contimg {\n        text-align: center;\n    }\n\n    button {\n        background-color: #F75697;\n        padding: 8px 16px;\n        border-radius: 6px;\n        outline: none;\n        color: white;\n        border: 0;\n    }\n\n    .lvst {\n        color: #57AC80;\n    }\n\n    .banquan {\n        display: flex;\n        justify-content: center;\n        flex-wrap: nowrap;\n        color: #B7B8B9;\n        font-size: 0.75rem;\n        padding: 20px 0;\n        margin: 0;\n        padding-left: 0;\n    }\n\n    .banquan li span {\n        display: inline-block;\n        padding: 0 8px;\n    }\n\n    @media (max-width: 650px) {\n        .card {\n            padding: 5% 5%;\n        }\n\n        .logo_top img,\n        .contimg img {\n            width: 280px;\n        }\n\n        .box {\n            height: auto;\n        }\n\n        .card {\n            width: auto;\n        }\n    }\n\n    @media (max-width: 280px) {\n\n        .logo_top img,\n        .contimg img {\n            width: 100%;\n        }\n    }\n</style>\n<div class="box">\n    <div class="logo_top"><img src="{site_logo}" alt=""/></div>\n    <div class="card">\n        <h1 style="text-align: center;">你有新的验证码<br/></h1></div><div class="card"><span style="font-size: 1.65rem;">您正在找回密码, 您的验证码是</span><span style="font-size: 0.8rem;">\n        </span><font size="10">{code}</font><span style="font-size: 1.65rem;">, 5 分钟内有效。如非本人操作请忽略</span><br/></div>\n    <div class="card card-footer">\n        <span class="left">{site_sitename}</span>\n        <span class="right">{time}</span>\n    </div>\n    <ul class="banquan">\n        <li>{site_company}<br/></li>\n    </ul>\n</div>', '', 1, 1688630239),
