            padding: 5% 5%;\n        }\n\n        .logo_top img,\n        .contimg img {\n            width: 280px;\n        }\n\n        .box {\n            height: auto;\n        }\n\n        .card {\n            width: auto;\n        }\n    }\n\n    @media (max-width: 280px) {\n\n        .logo_top img,\n        .contimg img {\n            width: 100%;\n        }\n    }\n</style>\n<div class="box">\n    <div class="logo_top"><img src="{site_logo}" alt=""/></div>\n    <div class="card">\n        <h1 style="text-align: center;">你有新的验证码<br/></h1><br/></div>\n    <div class="card"><span style="font-size: 1.65rem;">您正在修改邮箱, 您的验证码是</span>\n        <font size="10">{code}</font><span style="font-size: 1.65rem;">, 5 分钟内有效。如非本人操作请忽略</span>\n    </div>\n    <div class="card card-footer">\n        <span class="left">{site_sitename}</span>\n        <span class="right">{time}</span>\n    </div>\n    <ul class="banquan">\n        <li>{site_company}<br/></li>\n    </ul>\n</div>', NULL, 1, 1688641663),
(7, '下单成功', 'buyorder', '您已下单成功-{site_sitename}', '<meta charset="UTF-8">\n<meta http-equiv="X-UA-Compatible" content="IE=edge">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Document</title>\n<style>\n    li {\n        list-style: none;\n    }\n\n    a {\n        text-decoration: none;\n    }\n\n    html,\n    body {\n        margin: 0 !important;\n        font-size: 16px !important;\n    }\n\n    .box {\n        background-color: #f1f1f1;\n        height: 100%;\n        padding-bottom: 135px;\n    }\n\n    .logo_top {\n        padding: 20px 0;\n    width: 175px;  margin: auto;}\n\n    .logo_top img {\n        display: block;\n    width: 100%;\n        margin: 0 auto;\n}\n\n    .card {\n        width: 650px;\n        margin: 0 auto;\n        background-color: white;\n        font-size: 0.8rem;\n        line-height: 22px;\n        padding: 40px 50px;\n        box-sizing: border-box;\n    }\n\n    .card-footer {\n        display: flex;\n        justify-content: space-between;\n    }\n\n    .card-footer span.left {\n        font-size: 1.05rem;\n        display: inline-block;\n        width: 100%;\n        text-align: left;\n    }\n\n    .card-footer span.right {\n        font-size: 1.05rem;\n        display: inline-block;\n        width: 100%;\n        text-align: right;\n    }\n\n    .contimg {\n        text-align: center;\n    }\n\n    button {\n        background-color: #F75697;\n        padding: 8px 16px;\n        border-radius: 6px;\n        outline: none;\n        color: white;\n        border: 0;\n    }\n\n    .lvst {\n        color: #57AC80;\n    }\n\n    .banquan {\n        display: flex;\n        justify-content: center;\n        flex-wrap: nowrap;\n        color: #B7B8B9;\n        font-size: 0.75rem;\n        padding: 20px 0;\n        margin: 0;\n        padding-left: 0;\n    }\n\n    .banquan li span {\n        display: inline-block;\n        padding: 0 8px;\n    }\n\n    @media (max-width: 650px) {\n        .card {\n            padding: 5% 5%;\n        }\n\n        .logo_top img,\n        .contimg img {\n            width: 280px;\n        }\n\n        .box {\n            height: auto;\n        }\n\n        .card {\n            width: auto;\n        }\n    }\n\n    @media (max-width: 280px) {\n\n        .logo_top img,\n        .contimg img {\n            width: 100%;\n        }\n    }\n</style>\n<div class="box">\n    <div class="logo_top"><img src="{site_logo}" alt=""/></div>\n    <div class="card">\n        <h2 style="text-align: center;">下单成功通知</h2><br/></div>\n    <div class="card"><span style="font-size: 1.45rem;">您购买的商品</span><span style="background-color: rgb(241, 241, 241); font-size: 17px;">{order_name}</span><span style="font-size: 1.45rem;">已下单成功, 将尽快为你处理订单, 请耐心等待~</span></div>\n    <div class="card card-footer">\n        <span class="left">{site_sitename}</span>\n        <span class="right">{time}</span>\n    </div>\n    <ul class="banquan">\n        <li>{site_company}<br/></li>\n    </ul>\n</div>', NULL, 1, 1688641740),
(8, '修改密码', 'change_pwd', '您正在修改密码-{site_sitename}', '<meta charset="UTF-8">\n<meta http-equiv="X-UA-Compatible" content="IE=edge">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Document</title>\n<style>\n    li {\n        list-style: none;\n    }\n\n    a {\n        text-decoration: none;\n    }\n\n    html,\n    body {\n        margin: 0 !important;\n        font-size: 16px !important;\n    }\n\n    .box {\n        background-color: #f1f1f1;\n        height: 100%;\n        padding-bottom: 135px;\n    }\n\n    .logo_top {\n        padding: 20px 0;\n    width: 175px;  margin: auto;}\n\n    .logo_top img {\n        display: block;\n    width: 100%;\n        margin: 0 auto;\n}\n\n    .card {\n        width: 650px;\n        margin: 0 auto;\n        background-color: white;\n        font-size: 0.8rem;\n        line-height: 22px;\n        padding: 40px 50px;\n        box-sizing: border-box;\n    }\n\n    .card-footer {\n        display: flex;\n        justify-content: space-between;\n    }\n\n    .card-footer span.left {\n        font-size: 1.05rem;\n        display: inline-block;\n        width: 100%;\n        text-align: left;\n    }\n\n    .card-footer span.right {\n        font-size: 1.05rem;\n        display: inline-block;\n        width: 100%;\n        text-align: right;\n    }\n\n    .contimg {\n        text-align: center;\n    }\n\n    button {\n        background-color: #F75697;\n        padding: 8px 16px;\n        border-radius: 6px;\n        outline: none;\n        color: white;\n        border: 0;\n    }\n\n    .lvst {\n        color: #57AC80;\n    }\n\n    .banquan {\n        display: flex;\n        justify-content: center;\n        flex-wrap: nowrap;\n        color: #B7B8B9;\n        font-size: 0.75rem;\n        padding: 20px 0;\n        margin: 0;\n        padding-left: 0;\n    }\n\n    .banquan li span {\n        display: inline-block;\n        padding: 0 8px;\n    }\n\n    @media (max-width: 650px) {\n        .card {\n            padding: 5% 5%;\n        }\n\n        .logo_top img,\n        .contimg img {\n            width: 280px;\n        }\n\n        .box {\n            height: auto;\n        }\n\n        .card {\n            width: auto;\n        }\n    }\n\n    @media (max-width: 280px) {\n\n        .logo_top img,\n        .contimg img {\n            width: 100%;\n        }\n    }\n</style>\n<div class="box">\n    <div class="logo_top"><img src="{site_logo}" alt=""/></div>\n    <div class="card">\n        <h1 style="text-align: center;">你有新的验证码<br/></h1><br/></div>\n    <div class="card"><span style="font-size: 1.65rem;">您正在修改密码, 您的验证码是</span>\n        <font size="10">{code}</font><span style="font-size: 1.65rem;">, 5 分钟内有效。如非本人操作请忽略</span>\n    </div>\n    <div class="card card-footer">\n        <span class="left">{site_sitename}</span>\n        <span class="right">{time}</span>\n    </div>\n    <ul class="banquan">\n        <li>{site_company}<br/></li>\n    </ul>\n</div>', NULL, 1, 1688641876),
