            padding: 5% 5%;\n        }\n\n        .logo_top img,\n        .contimg img {\n            width: 280px;\n        }\n\n        .box {\n            height: auto;\n        }\n\n        .card {\n            width: auto;\n        }\n    }\n\n    @media (max-width: 280px) {\n\n        .logo_top img,\n        .contimg img {\n            width: 100%;\n        }\n    }\n</style>\n<div class="box">\n    <div class="logo_top"><img src="{site_logo}" alt=""/></div>\n    <div class="card">\n        <h1 style="text-align: center;">你有新的验证码<br/></h1><br/></div>\n    <div class="card"><span style="font-size: 1.65rem;">您正在进行重要操作, 您的验证码是</span>\n        <font size="10">{code}</font><span style="font-size: 1.65rem;">, 5 分钟内有效。如非本人操作请忽略</span>\n    </div>\n    <div class="card card-footer">\n        <span class="left">{site_sitename}</span>\n        <span class="right">{time}</span>\n    </div>\n    <ul class="banquan">\n        <li>{site_company}<br/></li>\n    </ul>\n</div>', NULL, 1, 1688641876);



ALTER TABLE `cmy_site` ADD `kfwx` VARCHAR(500)  NOT NULL DEFAULT '' COMMENT '客服链接';
ALTER TABLE `cmy_site` ADD `musicurl` VARCHAR(800) NOT NULL DEFAULT '' COMMENT '站点音乐链接';

ALTER TABLE `cmy_site` CHANGE `kfwx` `kfwx` VARCHAR(500)  NOT NULL DEFAULT '' COMMENT '客服链接';
ALTER TABLE `cmy_site` CHANGE `musicurl` `musicurl` VARCHAR(800) NOT NULL DEFAULT '' COMMENT '站点音乐链接';


ALTER TABLE `cmy_workorder` 
    ADD `sid` int(11) NOT NULL DEFAULT '0' COMMENT '供货商ID' after `id`;   

